#include <Arduino.h>
#include <Esp32LteClock.h>
static esp32_lte_time::Esp32LteClock receiver;
static void progress(esp32_lte_time::ClockStatus status,const esp32_lte_time::ClockEvidence& e){
 static uint32_t visit=0;static auto last=esp32_lte_time::ClockStatus::Idle;
 if(visit!=e.scanVisits||last!=status){
  Serial.printf("ATT_PROBE boot_ms=%u status=%u visit=%u carrier_kHz=%u PCI=%u captures=%u MIBs=%u\n",millis(),unsigned(status),e.scanVisits,e.carrier100kHz*100u,e.pci,e.captures,e.mibs);
  visit=e.scanVisits;last=status;
 }
}
void setup(){
 Serial.begin(115200);Serial.println("ATT_PROBE_START target_PLMN=310-410 no host time or serial input");
 esp32_lte_time::ClockConfig config;config.autoScan=true;config.capturesPerFrequency=4;
 config.cellAttempts=1;config.cellTimeoutMs=20000;config.gainIndex=68;
 bool synced=receiver.sync(600000,config,progress);
 const auto& e=receiver.evidence();
 Serial.printf("ATT_PROBE_RESULT synced=%u status=%u visits=%u captures=%u MIBs=%u carrier_kHz=%u PCI=%u cell=%u ticks=%llu\n",unsigned(synced),unsigned(receiver.status()),e.scanVisits,e.captures,e.mibs,e.carrier100kHz*100u,e.pci,e.cellId,(unsigned long long)e.rawTicks);
 Serial.println("ATT_PROBE_DONE");
}
void loop(){delay(1000);}

